files["routes.py"] = ""
files["routes2.py"] = ""
files["db.py"] = ""
files["auth.py"] = ""
files["styles.py"] = ""
files["requirements.txt"] = "Zmxhc2s+PTMuMC4wCm9wZW5jdi1jb250cmliLXB5dGhvbi1oZWFkbGVzcz09NC44LjEuNzgKbnVtcHk9PTEuMjYuNAptYXRwbG90bGliPT0zLjguNAp3ZXJremV1Zz49My4wLjAKZ3VuaWNvcm4+PTIxLjIuMAo="

for name, b64 in files.items():
    with open(name, "wb") as f:
        f.write(base64.b64decode(b64))
    print(f"✅ {name} written")

print("All files updated! Restart the service now.")